#include <bits/stdc++.h>using namespace std;#define int long long#define double long double bool f(int x, vector <int>& v, int n, int k) {     int sum = 0;    for (int i = (n / 2) ; i < n; i++) {        if (v[i] < x)            sum += (x - v[i]);    }    return sum <= k;}int32_t main() {    int n, k;     cin >> n >> k;    vector <int> v(n);    for (int i = 0; i < n; i++) {        cin >> v[i];    }    sort(v.begin(), v.end());    int left = 1, right = 2e9 + 5, answer = 0;    while (left <= right) {        int mid = left + (right - left) / 2;        if (f(mid, v, n, k)) {            left = mid + 1;            answer = mid;        } else {            right = mid - 1;        }    }    cout << answer << "\n";    return 0;}